```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch (approved grant). The result is intentionally not
        // used, so the node's output is unaffected, and a transport failure is
        // a value that we ignore.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&composed.overview)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let message = format!(
            "Digest {}: {} ({} entries)",
            composed.date,
            composed.overview,
            composed.entries.len()
        );
        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

